// ยืนยัน webhook ตอนตั้งค่าครั้งแรก (Meta ยิง GET มาพร้อม hub.challenge)
// VERIFY_TOKEN ต้องตรงกับที่กรอกใน Meta App → Messenger → Webhooks → Verify Token
const VERIFY_TOKEN = 'porpaor_fb_verify_2026';
const q = ($input.first().json.query) || {};
const mode = q['hub.mode'] || '';
const token = q['hub.verify_token'] || '';
const challenge = q['hub.challenge'] || '';
const ok = (mode === 'subscribe' && token === VERIFY_TOKEN);
return [{ json: { ok: ok, challenge: challenge } }];

// เก็บเฉพาะข้อความตัวอักษรที่ลูกค้าพิมพ์เข้ามาทาง Facebook Messenger
// เก็บเงียบๆ (capture-only) — ไม่ตอบกลับ, ไม่ต้องใช้ page access token
// เซ็นเซอร์เบอร์โทร (PDPA) + escape ' กัน SQL injection จากข้อความลูกค้า

// ⚙️ map: page id (entry.id) → แบรนด์ — เจ้าของต้องใส่ page id จริงของแต่ละเพจ
// (ดูได้ใน Meta: Graph API me?fields=id ตอนออก token / หน้าเพจ → เกี่ยวกับ → รหัสเพจ)
// ถ้า page id ไม่อยู่ใน map จะเก็บเป็น brand='unknown' (ไม่ทิ้งข้อมูล) แล้วค่อยแก้ map ทีหลัง
const PAGE_BRAND = {
  '274137326323079': 'honda',
  'PAGE_ID_YAMAHA':  'yamaha'
};

const body = $input.first().json.body || $input.first().json;
if (!body || body.object !== 'page') return [];
const entries = body.entry || [];
const esc = (s) => String(s).replace(/'/g, "''");
const rows = [];

for (const entry of entries) {
  const pageId = String(entry.id || '');
  const brand = PAGE_BRAND[pageId] || 'unknown';
  const events = entry.messaging || [];
  for (const ev of events) {
    const msg = ev.message;
    if (!msg || msg.is_echo) continue;   // ข้าม echo (ข้อความที่เพจส่งออก) + event ที่ไม่ใช่ message
    let text = (msg.text || '').trim();
    if (!text) continue;                 // ข้าม sticker/รูป/ไฟล์แนบ (เก็บเฉพาะ text)
    text = text.replace(/0[\d\s-]{8,12}/g, (m) => {
      const d = m.replace(/\D/g, '');
      return (d.length >= 9 && d.length <= 10) ? '[เบอร์โทร]' : m;
    });
    const psid = (ev.sender && ev.sender.id) ? ev.sender.id : '';
    rows.push({ json: {
      sql: "INSERT INTO messages (line_user_id, brand, source, message_type, text) VALUES ('"
        + esc(psid) + "', '" + esc(brand) + "', 'facebook', 'text', '" + esc(text) + "');"
    }});
  }
}
return rows;
